text:
{
  "steps": [
    {
      "step_id": 1,
      "time": null,
      "role": "市气象局",
      "action": "气象监测",
      "description": "市气象局加强气象监测预报，密切关注热带气旋或台风发展趋势，及时向市防指和各成员单位通报预报信息，做好发布台风预警准备。",
      "resources": []
    },
    {
      "step_id": 2,
      "time": null,
      "role": "市海洋局",
      "action": "海上管控",
      "description": "市海洋局统计出海渔船与人员数量，向厦门籍海上作业渔船发布台风预警信息，与渔船上的人员保持联系，提醒做好防台风工作。",
      "resources": []
    },
    {
      "step_id": 3,
      "time": null,
      "role": "应急指挥部",
      "action": "会商研判",
      "description": "市防指组织气象、海洋、水文等部门会商，分析台风可能对我市造成的影响程度，适时发出防御台风Ⅳ级应急响应的通知，作出防台风工作安排。必要时召开防台风工作会商部署视频会议，及时将情况上报市委、市政府和省防指。",
      "resources": []
    },
    {
      "step_id": 4,
      "time": null,
      "role": "市气象局",
      "action": "台风预警",
      "description": "市气象局组织做好台风的预测、预报和预警工作，下发有针对性的指导预报产品，根据台风发展趋势及时组织制作决策服务产品，将有关情况及时报市委办公厅、市政府办公厅、市防汛办。",
      "resources": []
    },
    {
      "step_id": 5,
      "time": null,
      "role": "应急指挥部",
      "action": "启动响应",
      "description": "市防指根据会商研判结果，启动防御台风Ⅳ级应急响应，发出通知部署防台风工作，要求各区各成员单位加强值班，密切关注台风发展趋势，随时准备做好进一步防范应对工作。防御台风应急响应全市各区统一启动、调整和结束。",
      "resources": []
    },
    {
      "step_id": 6,
      "time": null,
      "role": "市海洋局",
      "action": "船只回港",
      "description": "市海洋局通知并督促所有出海渔船回港避风，确保渔船和人员安全。",
      "resources": []
    },
    {
      "step_id": 7,
      "time": null,
      "role": "厦门海事局",
      "action": "船员上岸",
      "description": "厦门海事局组织海上作业人员、船员上岸避险，确保人员安全。",
      "resources": []
    },
    {
      "step_id": 8,
      "time": null,
      "role": "厦门海事局",
      "action": "船舶停航",
      "description": "厦门海事局发布航行警告，对海上船舶实施停航管控措施，组织船舶避风。",
      "resources": []
    },
    {
      "step_id": 9,
      "time": null,
      "role": "厦门港口局",
      "action": "港区防护",
      "description": "厦门港口局组织港区做好防台风工作，对港口设施进行防护加固，安排港口作业船舶避风。",
      "resources": []
    },
    {
      "step_id": 10,
      "time": null,
      "role": "市文旅局",
      "action": "景区关闭",
      "description": "市文旅局发布通知关闭沿海景区、景点，疏散游客，做好文旅场所防台风工作。",
      "resources": []
    },
    {
      "step_id": 11,
      "time": null,
      "role": "市建设局",
      "action": "工地停工",
      "description": "市建设局通知在建工地停止施工，对工地设施进行加固防护，组织施工人员撤离危险区域。",
      "resources": []
    },
    {
      "step_id": 12,
      "time": null,
      "role": "市市政园林局",
      "action": "设施防护",
      "description": "市市政园林局对市政设施、园林树木等进行防护加固，做好排涝准备。",
      "resources": []
    },
    {
      "step_id": 13,
      "time": null,
      "role": "市水利局",
      "action": "水库调度",
      "description": "市水利局做好水库调度工作，根据台风降雨预报提前预泄腾库，加强水情监测。",
      "resources": []
    },
    {
      "step_id": 14,
      "time": null,
      "role": "市交通局",
      "action": "公交停运",
      "description": "市交通局根据台风影响情况，适时发布公交停运指令，做好交通保障工作。",
      "resources": []
    },
    {
      "step_id": 15,
      "time": null,
      "role": "市教育局",
      "action": "停课指令",
      "description": "市教育局发布停课指令，通知全市学校停课，做好校园安全防护工作。",
      "resources": []
    },
    {
      "step_id": 16,
      "time": null,
      "role": "市教育局",
      "action": "学校停课",
      "description": "各学校落实停课指令，组织学生安全离校，做好留校学生安置和校园防台风工作。",
      "resources": []
    },
    {
      "step_id": 17,
      "time": null,
      "role": "市商务局",
      "action": "休市落实",
      "description": "市商务局发布休市通知，落实市场休市措施，做好市场监测和物资供应保障。",
      "resources": []
    },
    {
      "step_id": 18,
      "time": null,
      "role": "市政府",
      "action": "动员批准",
      "description": "市防指提请市委或市政府主要领导召开各成员单位主要领导和专家以及各区参加的会商部署会，研究部署防御工作。市防指发出防御超强台风的通知，研究宣布进入紧急防汛期、发布“三停一休”动员令，号召全社会做好防汛救灾工作。",
      "resources": []
    },
    {
      "step_id": 19,
      "time": null,
      "role": "应急指挥部",
      "action": "三停一休",
      "description": "市防指发布“三停一休”动员令，全市实行停工、停课、停业、休市，号召全社会做好防汛救灾工作。",
      "resources": []
    },
    {
      "step_id": 20,
      "time": null,
      "role": "应急指挥部",
      "action": "响应调整",
      "description": "市防指根据台风发展变化情况，适时调整防御台风应急响应级别和管制措施，各主管部门相应调整相关管制措施，同时报市防指。",
      "resources": []
    },
    {
      "step_id": 21,
      "time": null,
      "role": "市气象局",
      "action": "气象监测",
      "description": "市气象局每隔1小时作出台风预测预报，及时作出台风可能登陆地点、时间、移动路径、风雨量级和风险等级的预报。厦门海洋环境预报台加密海洋灾害的监测预警，每隔1小时作出风暴潮预测预报、通报实测潮位。市水文局及时作出山洪灾害预测预报，并报市委办公厅、市政府办公厅、市防汛办。",
      "resources": []
    },
    {
      "step_id": 22,
      "time": null,
      "role": "交通管制组",
      "action": "交通管制",
      "description": "市公安局交警支队对沿海危险区域道路实施交通管制，设置警戒线，禁止无关车辆和人员进入危险区域。",
      "resources": []
    },
    {
      "step_id": 23,
      "time": null,
      "role": "市交警支队",
      "action": "交通疏导",
      "description": "市交警支队在主要道路和路口开展交通疏导，保障应急救援车辆通行顺畅。",
      "resources": []
    },
    {
      "step_id": 24,
      "time": null,
      "role": "交通管制组",
      "action": "现场警戒",
      "description": "交通管制组在危险区域设置现场警戒，维护治安秩序，防止人员擅自进入危险区域。",
      "resources": []
    },
    {
      "step_id": 25,
      "time": null,
      "role": "区政府",
      "action": "人员转移",
      "description": "各区政府组织沿海区域、低洼地带、危旧房屋等危险区域人员转移，确保应转尽转、不漏一人。",
      "resources": []
    },
    {
      "step_id": 26,
      "time": null,
      "role": "社区/基层",
      "action": "人员转移引导",
      "description": "社区/基层工作人员按照转移预案，引导危险区域群众有序转移至安全区域或安置点。",
      "resources": []
    },
    {
      "step_id": 27,
      "time": null,
      "role": "市应急局",
      "action": "安置点开放",
      "description": "市应急局和区政府开放安置点，做好安置点物资准备和人员接收工作。",
      "resources": [
        {
          "resource_type": "帐篷",
          "quantity": 50
        }
      ]
    },
    {
      "step_id": 28,
      "time": null,
      "role": "市应急局",
      "action": "安置救助",
      "description": "市应急局和区政府做好转移群众的安置救助工作，提供基本生活保障，确保安置群众有饭吃、有水喝、有地方住。",
      "resources": [
        {
          "resource_type": "急救包",
          "quantity": 30
        }
      ]
    },
    {
      "step_id": 29,
      "time": null,
      "role": "市海洋局",
      "action": "渔船出港",
      "description": "台风影响解除后，市海洋局通知渔船有序出港恢复生产。",
      "resources": []
    },
    {
      "step_id": 30,
      "time": null,
      "role": "市市政园林局",
      "action": "排涝作业",
      "description": "市市政园林局组织排涝队伍和设备，对城市低洼地带、下穿通道等积水区域开展排涝作业，尽快恢复交通和正常生活秩序。",
      "resources": [
        {
          "resource_type": "排水泵",
          "quantity": 10
        },
        {
          "resource_type": "抢修车辆",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 31,
      "time": null,
      "role": "工程抢险组",
      "action": "现场处置",
      "description": "工程抢险组对险情进行现场处置，组织抢修受损设施，尽快恢复水、电、气、通讯、道路等基础设施。",
      "resources": [
        {
          "resource_type": "挖掘机",
          "quantity": 3
        },
        {
          "resource_type": "吊装设备",
          "quantity": 2
        }
      ]
    },
    {
      "step_id": 32,
      "time": null,
      "role": "国网厦门供电公司",
      "action": "电力保障",
      "description": "国网厦门供电公司组织抢修队伍对受损电力设施进行抢修，保障应急供电和居民生活用电。",
      "resources": [
        {
          "resource_type": "发电机",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 33,
      "time": null,
      "role": "市通信管理局",
      "action": "通信保障",
      "description": "市通信管理局组织通信运营企业抢修受损通信设施，保障应急通信畅通。",
      "resources": [
        {
          "resource_type": "卫星电话",
          "quantity": 5
        }
      ]
    },
    {
      "step_id": 34,
      "time": null,
      "role": "区政府",
      "action": "险情巡查",
      "description": "各区各成员单位对沿海区域、低洼地带、地质灾害隐患点等开展险情巡查，发现灾险情及时处理并报告。各级责任人全部上岗到位，全面落实各项防御措施。",
      "resources": [
        {
          "resource_type": "无人机",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 35,
      "time": null,
      "role": "市消防救援支队",
      "action": "救援搜救",
      "description": "市消防救援支队组织消防救援力量，对被困人员进行搜救和救援。",
      "resources": [
        {
          "resource_type": "冲锋舟",
          "quantity": 5
        },
        {
          "resource_type": "消防车",
          "quantity": 3
        }
      ]
    },
    {
      "step_id": 36,
      "time": null,
      "role": "医疗救护组",
      "action": "医疗救护",
      "description": "医疗救护组组织医疗队赴一线开展医疗救助，对受伤人员进行救治。",
      "resources": [
        {
          "resource_type": "救护车",
          "quantity": 3
        },
        {
          "resource_type": "急救包",
          "quantity": 20
        }
      ]
    },
    {
      "step_id": 37,
      "time": null,
      "role": "市卫健委",
      "action": "卫生防疫",
      "description": "市卫健委组织防疫消杀队伍，对受灾区域开展卫生防疫和防疫消杀工作，防止疫情发生。",
      "resources": []
    },
    {
      "step_id": 38,
      "time": null,
      "role": "市应急局",
      "action": "灾情统计",
      "description": "各区各成员单位及时核实、更新防御工作动态和受灾情况，市应急局汇总统计灾情信息。",
      "resources": []
    },
    {
      "step_id": 39,
      "time": null,
      "role": "市气象局",
      "action": "影响解除",
      "description": "市气象局发布台风影响解除信息，确认台风影响已结束。",
      "resources": []
    },
    {
      "step_id": 40,
      "time": null,
      "role": "应急指挥部",
      "action": "响应终止",
      "description": "市防指根据气象部门台风影响解除信息，宣布终止防御台风应急响应，转入救灾恢复重建阶段。",
      "resources": []
    },
    {
      "step_id": 41,
      "time": null,
      "role": "区政府",
      "action": "灾情稳定",
      "description": "各区政府组织做好灾民安置救助工作，确保灾区社会秩序稳定，做好灾后恢复重建工作。",
      "resources": []
    },
    {
      "step_id": 42,
      "time": null,
      "role": "市应急局",
      "action": "灾损评估",
      "description": "灾情稳定后，市减灾委组织对灾害损失进行全面评估，相关部门做好灾后人员救助和安置工作。",
      "resources": []
    },
    {
      "step_id": 43,
      "time": null,
      "role": "区政府",
      "action": "复工复课",
      "description": "各区政府和市教育局根据灾情评估情况，组织复工复课，尽快恢复生产、生活秩序。",
      "resources": []
    },
    {
      "step_id": 44,
      "time": null,
      "role": "市委宣传部",
      "action": "宣传引导",
      "description": "市委宣传部组织新闻媒体加大宣传力度，做好抢险救灾宣传工作，及时发布权威信息，引导社会舆论。",
      "resources": []
    }
  ]
}
